def toggle(state, n, i, j):
    for di, dj in ((0, 0), (1, 0), (-1, 0), (0, 1), (0, -1)):
        a, b = i + di, j + dj
        if 0 <= a < n and 0 <= b < n:
            state[a][b] ^= 1

